def transform(grid):
    if not grid:
        return grid

    H = len(grid)
    W = len(grid[0])

    # Identify background color (most frequent)
    counts = {}
    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1

    if not counts:
        return grid
    bg = max(counts, key=counts.get)

    # Store changes to handle simultaneous updates correctly
    # Key: (r, c), Value: color
    changes = {}

    # Iterate over all 2x2 windows
    for r in range(H - 1):
        for c in range(W - 1):
            # Extract window cells
            v_tl = grid[r][c]
            v_tr = grid[r][c+1]
            v_bl = grid[r+1][c]
            v_br = grid[r+1][c+1]
            vals = [v_tl, v_tr, v_bl, v_br]

            # Count occurrences of each value in the window
            vals_counts = {}
            for v in vals:
                vals_counts[v] = vals_counts.get(v, 0) + 1

            # Look for 3 identical cells of a non-background color
            for color, cnt in vals_counts.items():
                if cnt == 3 and color != bg:
                    # Identify the position of the gap (the 4th cell)
                    gap_r, gap_c = -1, -1

                    if v_tl != color:
                        gap_r, gap_c = r, c
                    elif v_tr != color:
                        gap_r, gap_c = r, c+1
                    elif v_bl != color:
                        gap_r, gap_c = r+1, c
                    elif v_br != color:
                        gap_r, gap_c = r+1, c+1

                    # Determine ray direction based on gap position relative to the 2x2 center
                    # Center of window is at (r+0.5, c+0.5)
                    # Gap vector = Gap - Center
                    if gap_r == r and gap_c == c:      # Top-Left Gap -> Up-Left
                        dr, dc = -1, -1
                    elif gap_r == r and gap_c == c+1:  # Top-Right Gap -> Up-Right
                        dr, dc = -1, 1
                    elif gap_r == r+1 and gap_c == c:  # Bottom-Left Gap -> Down-Left
                        dr, dc = 1, -1
                    elif gap_r == r+1 and gap_c == c+1:# Bottom-Right Gap -> Down-Right
                        dr, dc = 1, 1
                    else:
                        continue

                    # Fill the gap if not already filled
                    if (gap_r, gap_c) not in changes:
                        changes[(gap_r, gap_c)] = color

                    # Emit ray from the gap in the determined direction
                    cur_r, cur_c = gap_r + dr, gap_c + dc
                    while 0 <= cur_r < H and 0 <= cur_c < W:
                        cell_val = grid[cur_r][cur_c]

                        # Stop if hitting a non-background cell that is not the ray color (blockage)
                        if cell_val != bg and cell_val != color:
                            break

                        # Fill if not already filled
                        if (cur_r, cur_c) not in changes:
                            changes[(cur_r, cur_c)] = color

                        cur_r += dr
                        cur_c += dc

    # Apply all planned changes to the grid
    for (r, c), val in changes.items():
        grid[r][c] = val

    return grid
